// Land for routes.js: Natural Earth 1:110m land (public domain, naturalearthdata.com; ne_110m_land.geojson from
// nvkelso/natural-earth-vector v5.1.2), sampled on a 40 000-point Fibonacci sphere: the 11 546 points on land.
// base64 of little-endian Int16 pairs (lat * 100, lon * 100).
export const LAND = "";

// [lat0, lon0, lat1, lon1, ...] in degrees
export function landDots() {
  const bin = atob(LAND), view = new DataView(new ArrayBuffer(bin.length));
  for (let i = 0; i < bin.length; i++) view.setUint8(i, bin.charCodeAt(i));
  const out = new Float32Array(bin.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = view.getInt16(i * 2, true) / 100;
  return out;
}
